# Miller backward iteration for slow adjoint
# Adjoint: w_n = alpha(n+2)*w_{n+1} + beta(n+3)*w_{n+2} + gamma(n+4)*w_{n+3}
def miller(M, seed):
    w = [RF(_sage_const_0 )]*(M+_sage_const_3 )
    w[M] = RF(seed[_sage_const_0 ])
    w[M+_sage_const_1 ] = RF(seed[_sage_const_1 ])
    w[M+_sage_const_2 ] = RF(seed[_sage_const_2 ])
    for n in range(M-_sage_const_1 , -_sage_const_1 , -_sage_const_1 ):
        w[n] = alpha(n+_sage_const_2 )*w[n+_sage_const_1 ] + beta(n+_sage_const_3 )*w[n+_sage_const_2 ] + gamma(n+_sage_const_4 )*w[n+_sage_const_3 ]
